#!/bin/bash

# Required parameters:
# @raycast.schemaVersion 1
# @raycast.title Tabbed Column
# @raycast.mode silent
# @raycast.packageName Spool

# Optional parameters:
# @raycast.icon 🗂️
# @raycast.description Tabbed Column. Runs: spool toggle-tabbed

# Generated by generate.sh. Do not edit: change the list in generate.sh and run it again.

cmd="toggle-tabbed"

find_cli() {
  command -v spool 2>/dev/null && return
  # Raycast does not load your shell profile, so also look in the usual places.
  for p in "$HOME/.local/bin/spool" /Applications/Spool.app/Contents/Helpers/spool; do
    if [ -x "$p" ]; then echo "$p"; return; fi
  done
}

cli="$(find_cli)"
if [ -z "$cli" ]; then
  # No CLI: the URL scheme runs the same command (and opens Spool if needed).
  open -g "spool://$cmd"
  exit
fi
out="$("$cli" "$cmd" 2>&1)"
status=$?
if [ "$status" -ne 3 ]; then
  [ -z "$out" ] || echo "$out"
  exit "$status"
fi
# Exit code 3: Spool is not running. The URL opens Spool and runs the command.
open -g "spool://$cmd"
